{
  "name": "ble_ll_control_parse",
  "confidence": "medium",
  "docstring": "Parses a Bluetooth LE link-layer control message, allocates an HCI event buffer when appropriate, and packs and sends the resulting event.",
  "subsystem": "ble",
  "var_renames": {
    "result": "msg_ptr",
    "v3": "ll_base",
    "v4": "msg_ptr",
    "v5": "link_idx",
    "v15": "control_flags",
    "v17": "control_payload_ptr",
    "v27": "event_pool_ptr",
    "v30": "event_buf_ptr",
    "v31": "alloc_counter_ptr"
  },
  "struct_hints": [
    {
      "offset": 7,
      "meaning": "message byte field; 255 is treated as a special wildcard or invalid value"
    },
    {
      "offset": 8,
      "meaning": "link or connection index used to select a 1320-byte BLE link-layer entry"
    },
    {
      "offset": 12,
      "meaning": "control message opcode or type byte"
    },
    {
      "offset": 13,
      "meaning": "subtype or field selector within the control message"
    },
    {
      "offset": 17,
      "meaning": "control flag byte parsed from the message"
    },
    {
      "offset": 18,
      "meaning": "16-bit control field following the flag byte"
    },
    {
      "offset": 108,
      "meaning": "byte flag in a BLE link-layer connection/context entry"
    },
    {
      "offset": 472,
      "meaning": "uint32 status word in a BLE link-layer connection/context entry"
    }
  ]
}
